toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #202225;
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #8e9297;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
    padding: 8px 0;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #36393f;
}

.channel-item.active {
    background: #393c43;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
}

.channel-desc {
    width: 100%;
    font-size: 0.75rem;
    color: #72767d;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.unread-badge {
    background: #ed4245;
    color: #fff;
    border-radius: 10px;
    padding: 2px 6px;
    font-size: 0.7rem;
    font-weight: 700;
    min-width: 18px;
    text-align: center;
}

/* Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
    min-width: 0;
}

.area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #8e9297;
    font-size: 0.85rem;
}

/* Message Bubble */
.message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

.message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #4f545c;
}

.thread-link {
    margin-top: 4px;
    font-size: 0.8rem;
    color: #00aff4;
    cursor: pointer;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Message Actions (on hover) */
.message-actions {
    position: absolute;
    top: -12px;
    right: 12px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    display: flex;
    gap: 2px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    padding: 4px 8px;
    border-radius: 3px;
    cursor: pointer;
    font-size: 0.75rem;
    white-space: nowrap;
}

.action-btn:hover {
    background: #4f545c;
    color: #fff;
}

.emoji-picker {
    position: absolute;
    top: -12px;
    right: 140px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 6px;
    padding: 6px;
    display: flex;
    gap: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.emoji-option {
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #4f545c;
}

/* Message Input */
.message-input {
    padding: 12px 20px;
    border-top: 1px solid #202225;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-input textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 6px;
    color: #dcddde;
    padding: 10px 12px;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

.message-input textarea::placeholder {
    color: #72767d;
}

.btn-send {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 10px 16px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
    transition: background 0.15s;
}

.btn-send:hover:not(:disabled) {
    background: #4752c4;
}

.btn-send:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    color: #dcddde;
    border-left: 1px solid #202225;
    display: flex;
    flex-direction: column;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.btn-close-thread {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.btn-close-thread:hover {
    background: #4f545c;
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    margin-top: 4px;
    font-size: 0.85rem;
    color: #b9bbbe;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.thread-reply {
    padding: 6px 0;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}

/* Layout adjustments for thread open/closed */
.chat-layout.thread-open .message-area {
    width: 55%;
}

.chat-layout:not(.thread-open) .message-area {
    width: 80%;
}

